#include <vector>
#include <algorithm>

class Solution {
public:
    int maxFixedPoints(std::vector<int>& nums) {
        std::vector<std::pair<int, int>> candidates;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int v = nums[i];
            if (v <= i && v >= 0) {
                candidates.push_back({v, i - v});
            }
        }
        std::sort(candidates.begin(), candidates.end(), [](const auto& a, const auto& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second > b.second;
        });
        std::vector<int> tails;
        for (const auto& [v, d] : candidates) {
            auto it = std::upper_bound(tails.begin(), tails.end(), d);
            if (it == tails.end()) {
                tails.push_back(d);
            } else {
                *it = d;
            }
        }
        return tails.size();
    }
};

import java.util.*;

class Solution {
    public int maxFixedPoints(int[] nums) {
        List<int[]> candidates = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            if (v <= i && v >= 0) {
                candidates.add(new int[]{v, i - v});
            }
        }
        candidates.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(b[1], a[1]);
        });
        List<Integer> tails = new ArrayList<>();
        for (int[] cand : candidates) {
            int d = cand[1];
            int low = 0, high = tails.size();
            while (low < high) {
                int mid = (low + high) / 2;
                if (tails.get(mid) <= d) low = mid + 1;
                else high = mid;
            }
            if (low == tails.size()) {
                tails.add(d);
            } else {
                tails.set(low, d);
            }
        }
        return tails.size();
    }
}

function maxFixedPoints(nums) {
    const candidates = [];
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (v <= i && v >= 0) {
            candidates.push([v, i - v]);
        }
    }
    candidates.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        return b[1] - a[1];
    });
    const tails = [];
    for (const [v, d] of candidates) {
        let low = 0, high = tails.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (tails[mid] <= d) low = mid + 1;
            else high = mid;
        }
        if (low === tails.length) {
            tails.push(d);
        } else {
            tails[low] = d;
        }
    }
    return tails.length;
}
